  const count = Math.round(3 + 17 * k);
  const len = 60 + 180 * k;
  const vRange = 40 + 160 * k;
  const jitterAmp = 2 + 6 * k;
  ch.vRange = vRange;
  ch.split = 2 + 10 * k;
  const tk = Math.floor(ch.time * (16 + 30 * k));
