  /* ---- 配色 · 右键（延迟爆发）橙金红组 ---- */
  R_MAIN: [255, 140, 26],
  // 橙
  R_SUB: [255, 61, 93],
  // 红
  R_HI: [255, 210, 74],
  // 金
  R_DARK: [74, 26, 26],
  // 暗红
  R_GHOST: [138, 74, 42],
  // 残影淡色 暗橙
  /* ---- 时间冻结（左键）---- */
