    const pal = FORGE_PALETTE[Math.max(st, 0)];
    const R = CONFIG8.FORGE.RADII[Math.max(st, 0)];
    const shape = FORGE_SHAPES[Math.max(st, 0)];
    const pf = 2 + st * 0.8;
