  moon.active = true;
  moon.mode = "crater";
  moon.x = x;
  moon.y = y;
  moon.dx = 0;
  moon.dy = 0;
  moon.r = CONFIG14.moon.craterR;
  moon.phase = Math.PI;
  moon.charge = 0;
  moon.birth = 0.2;
  moon.pulse = 0;
  moon.exposure = 0;
  moon.dying = false;
  moon.dieT = 0;
