  const cnt = randInt(2, 3);
  for (let i = 0; i < cnt; i++) {
    const a = Math.random() * TAU;
    const d = Math.random() * moon.r * 0.6;
    impact(s, x + Math.cos(a) * d, y + Math.sin(a) * d, rand(3, 9));
  }
