  c.active = false;
  const cx = c.x, cy = c.y;
  const upV = weak ? 140 + 260 * power : 300 + 1e3 * power;
  for (let i = 0; i < c.members.length; i++) {
    const p = c.members[i];
    if (!p.alive) continue;
    p.cluster = null;
    p.kind = 0;
    const a = Math.random() * TAU;
    const sx = Math.cos(a) * (40 + power * 150);
    p.vx = sx;
    p.driftVx = sx;
    p.vy = -upV * rand(0.72, 1.3);
    p.buoy = rand(CONFIG15.BUOY_MIN, CONFIG15.BUOY_MAX);
    p.maxLife = p.life + rand(6, 14);
    p.flash = 0.95;
    p.stretch = 0.14;
    p.thick = Math.max(0.6, p.thick);
    if (!weak && Math.random() < 0.15) {
      p.overExpand = true;
      p.overTimer = rand(0.22, 0.7);
    }
  }
