  const _hw = s.scratch.hw;
  const lr = p.age / p.life;
  const grow = Math.min(1, p.age / (p.life * 0.28));
  const fade = 1 - Math.max(0, (lr - 0.62) / 0.38) * 0.85;
  let sizeK = grow * fade;
  if (sizeK <= 0.01) return;
  sizeK *= 1 + 0.3 * p.flash;
  const L = p.len * sizeK;
  if (L < 2.5) return;
  const N = 6;
  const step = L / (N - 1);
