  diskInnerGap: 5,
  // 吸积盘内半径 = 事件视界半径 + 该值
  diskOuterStart: 100,
  // 蓄力初期吸积盘外半径
  diskOuterEnd: 250,
  // 蓄满时吸积盘外半径
  diskFlatten: 0.42,
  // 椭圆扁率（倾斜透视，必须有明确的近端/远端）
